                    _fail("data values must be finite numbers")
        attrs = piece["attrs"]
        if not isinstance(attrs, dict):
            _fail("attrs must be an object")
        for key in attrs:
            if not isinstance(key, str):
                _fail("attrs keys must be strings")
        seen_coordinates.extend(coordinates)
        parsed.append((pid, coordinates, data, attrs))
    if len(set(seen_coordinates)) != len(seen_coordinates):
        _fail("coordinates must be unique across pieces (no overlap)")
    return columns, parsed, policy


def _parse_index(payload):
    result = _unwrap(payload)
    if not isinstance(result, dict):
        _fail("segment_index result must be an object")
    for key in ("columns", "order"):
        if key not in result:
            _fail("segment_index result missing field: %s" % key)
    columns = result["columns"]
    if not isinstance(columns, list):
        _fail("segment_index columns must be a list")
    for column in columns:
        if not _is_name(column):
            _fail("segment_index column names must be non-empty strings")
    order = result["order"]
    if not isinstance(order, list):
        _fail("segment_index order must be a list")
    entries = []
    for entry in order:
        if not isinstance(entry, dict):
            _fail("order entries must be objects")
        for key in ("coordinate", "piece", "row"):
            if key not in entry:
                _fail("order entry missing field: %s" % key)
        if not _is_number(entry["coordinate"]):
            _fail("order coordinate must be a finite number")
        if not _is_name(entry["piece"]):
            _fail("order piece must be a non-empty string")
        row = entry["row"]
        if not isinstance(row, int) or isinstance(row, bool):
            _fail("order row must be an integer")
        entries.append((entry["coordinate"], entry["piece"], row))
    return columns, entries


def _parse_attributes(payload):
    result = _unwrap(payload)
    if not isinstance(result, dict):
        _fail("segment_attributes result must be an object")
    for key in ("attrs", "conflicts"):
        if key not in result:
            _fail("segment_attributes result missing field: %s" % key)
    attrs = result["attrs"]
    if not isinstance(attrs, dict):
        _fail("merged attrs must be an object")
    for key in attrs:
        if not isinstance(key, str):
            _fail("attrs keys must be strings")
    conflicts = result["conflicts"]
    if not isinstance(conflicts, list):
        _fail("conflicts must be a list")
    for key in conflicts:
        if not isinstance(key, str):
            _fail("conflicts entries must be strings")
    return attrs, conflicts


def _check_contract(payloads, contract, count):
    if not isinstance(contract, dict):
        _fail("contract must be an object")
    for key in ("name", "inputs"):
        if key not in contract:
            _fail("contract missing field: %s" % key)
    inputs = contract["inputs"]
    if not isinstance(inputs, list) or not isinstance(payloads, list):
        _fail("contract inputs must be a list")
    if len(payloads) != len(inputs):
        _fail("payload count must match contract inputs")
    if len(payloads) != count:
        _fail("expected %d input payloads" % count)


def transform(payloads, contract):
    _check_contract(payloads, contract, 3)
    columns, pieces, _policy = _parse_segments(payloads[0])
    index_columns, order = _parse_index(payloads[1])
    attrs, conflicts = _parse_attributes(payloads[2])
    if list(index_columns) != list(columns):
        _fail("segment_index columns disagree with the input columns")
    by_id = {}
    for pid, coordinates, data, _piece_attrs in pieces:
        by_id[pid] = data
    coordinates_out = []
    data_out = []
    for coordinate, pid, row in order:
        data = by_id.get(pid)
        if data is None:
            _fail("order references unknown piece: %s" % pid)
        if row < 0 or row >= len(data):
            _fail("order row out of range for piece: %s" % pid)
        coordinates_out.append(coordinate)
        data_out.append(list(data[row]))
    return {
        "name": contract["name"],
        "result": {
            "coordinates": coordinates_out,
            "columns": list(columns),
            "data": data_out,
            "attrs": attrs,
            "attribute_conflicts": list(conflicts),
        },
    }

"""Workspace orchestrator: run every component from its file contract."""
import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _fail(message):
    print("run_all: %s" % message, file=sys.stderr)
    raise SystemExit(1)


def _load_contracts():
    contracts = []
    for cp in sorted(ROOT.rglob("contract.json")):
        if "outputs" in cp.relative_to(ROOT).parts:
            continue
        try:
            contract = json.loads(cp.read_text(encoding="utf-8"))
        except ValueError as exc:
            _fail("invalid contract %s: %s" % (cp, exc))
        if not isinstance(contract, dict):
            _fail("contract must be an object: %s" % cp)
        for key in ("name", "operation", "inputs", "output"):
            if key not in contract:
                _fail("contract missing %s: %s" % (key, cp))
        if not isinstance(contract["inputs"], list):
            _fail("contract inputs must be a list: %s" % cp)
        contracts.append((cp, contract))
    if not contracts:
        _fail("no contracts found")
    return contracts


def _norm(rel):
    return Path(rel).as_posix()


def _order_contracts(contracts):
    outputs = {}
    for cp, contract in contracts:
        out = _norm(contract["output"])
        if out in outputs:
            _fail("duplicate output path: %s" % out)
        outputs[out] = cp
    deps = {}
    for cp, contract in contracts:
        wanted = set()
        for raw in contract["inputs"]:
            rel = _norm(raw)
            producer = outputs.get(rel)
            if producer is None:
                if not (ROOT / rel).is_file():
                    _fail("missing input dependency: %s" % rel)
            elif producer == cp:
                _fail("component depends on its own output: %s" % cp)
            else:
                wanted.add(producer)
        deps[cp] = wanted
    remaining = dict(deps)
    order = []
    while remaining:
        ready = sorted(
            (cp for cp, wanted in remaining.items() if not (wanted & set(remaining))),
            key=lambda p: p.as_posix(),
        )
        if not ready:
            _fail("dependency cycle among contracts")
        for cp in ready:
            order.append(cp)
            del remaining[cp]
    return order


def main():
    contracts = _load_contracts()
    order = _order_contracts(contracts)
    for cp in order:
        render = cp.with_name("render.py")
        if not render.is_file():
            _fail("missing render.py for %s" % cp)
        subprocess.run([sys.executable, str(render)], cwd=str(ROOT), check=True)
    for script in ("integrate.py", "final_report.py"):
        path = ROOT / script
        if not path.is_file():
            _fail("missing %s" % script)
        subprocess.run([sys.executable, str(path)], cwd=str(ROOT), check=True)


if __name__ == "__main__":
    main()

"""Final report over the integrated core manifest."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
TITLE = "单变化轴的数据分片拼接"
FALSE_KEYS = ("complete", "checkout", "committed", "ok")
NONEMPTY_KEYS = ("unavailable", "missing", "conflicts", "unreachable")


def _is_nonempty(value):
    if value is None:
        return False
    if isinstance(value, (str, list, dict, tuple, set)):
        return len(value) > 0
    return bool(value)


def _attention(components):
    names = set()
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            names.add(name)
        for key in FALSE_KEYS:
            if result.get(key) is False:
                names.add(name)
        for key in NONEMPTY_KEYS:
            if _is_nonempty(result.get(key)):
                names.add(name)
    return sorted(names)


def main():
    core_path = ROOT / "outputs" / "core_manifest.json"
    core = json.loads(core_path.read_text(encoding="utf-8"))
    if not isinstance(core, dict) or "components" not in core:
        raise ValueError("core manifest must contain components")
    components = core["components"]
    if not isinstance(components, dict) or not isinstance(components, dict):
        raise ValueError("components must be an object")
    payload = json.dumps(core, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
    report = {
        "title": TITLE,
        "component_count": len(components),
        "sha256": hashlib.sha256(payload.encode("utf-8")).hexdigest(),
        "attention": _attention(components),
    }
    out = ROOT / "outputs" / "final_report.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()

